using Licitaciones.Domain.TiposCambio;
namespace Licitaciones.Application.TiposCambio;
public interface ITipoCambioRepository { Task AgregarAsync(TipoCambio t, CancellationToken c = default); Task<TipoCambio?> ObtenerAsync(Guid id, CancellationToken c = default); Task<IReadOnlyList<TipoCambio>> ListarAsync(CancellationToken c = default); Task<TipoCambio?> ObtenerActivoAsync(CancellationToken c = default); Task GuardarAsync(CancellationToken c = default); Task EliminarAsync(TipoCambio t, CancellationToken c = default); }
public sealed class TipoCambioService(ITipoCambioRepository repo, TimeProvider? reloj = null) { private readonly TimeProvider reloj = reloj ?? TimeProvider.System; public async Task<TipoCambio> CrearAsync(decimal v, bool activo, CancellationToken c = default) { var t = new TipoCambio(v, reloj.GetUtcNow()); if (activo) { await ActivarUnico(t, c); } await repo.AgregarAsync(t, c); return t; } public Task<IReadOnlyList<TipoCambio>> ListarAsync(CancellationToken c = default) => repo.ListarAsync(c); public async Task<TipoCambio> ObtenerAsync(Guid id, CancellationToken c = default) => await repo.ObtenerAsync(id, c) ?? throw new KeyNotFoundException("El tipo de cambio no existe."); public async Task EditarAsync(Guid id, decimal v, bool activo, CancellationToken c = default) { var t = await ObtenerAsync(id, c); t.Editar(v, reloj.GetUtcNow()); if (activo) await ActivarUnico(t, c); else t.Desactivar(reloj.GetUtcNow()); await repo.GuardarAsync(c); } public async Task EliminarAsync(Guid id, CancellationToken c = default) { var t = await ObtenerAsync(id, c); if (t.Activo) throw new InvalidOperationException("No se puede eliminar el tipo de cambio activo."); await repo.EliminarAsync(t, c); } public Task<TipoCambio> ActivoAsync(CancellationToken c = default) => repo.ObtenerActivoAsync(c).ContinueWith(t => t.Result ?? throw new KeyNotFoundException("No existe un tipo de cambio activo."), c); public async Task<decimal> ConvertirCrcAUsdAsync(decimal crc, CancellationToken c = default) { if (crc < 0) throw new ArgumentException("El monto CRC no puede ser negativo."); return crc / (await ActivoAsync(c)).CrcPorUsd; } private async Task ActivarUnico(TipoCambio t, CancellationToken c) { var actual = await repo.ObtenerActivoAsync(c); if (actual is not null && actual.Id != t.Id) { actual.Desactivar(reloj.GetUtcNow()); } t.Activar(reloj.GetUtcNow()); } }
